const FULL_SIGNATURE_BLOCK_RE = /(?:Regards|Best regards|Kind regards)?[,\s]*\n*Abdullah\s+Rauf[\s\S]*$/i;
const LEGACY_SIGNATURE_RE = /(?:Regards|Best regards|Kind regards)[,\s]*\n*MineTech\s+Outbound[\s.]*$/i;
const GENERIC_CLOSING_RE = /(?:Best regards|Regards|Kind regards|Warmly|Sincerely|Cheers|Thanks|Best)[,\s]*(?:\n*(?:\[.*?\]|[A-Za-z\s]+)?)?$/i;

const HTML_SIGNATURE_IDENTIFIER_RE = /Abdullah\s+Rauf|Kernenergiestraat\s+19|BE\s*1011004868/i;
const LEGACY_HTML_SIGNATURE_RE = /<p>\s*(?:Regards|Best regards|Kind regards)[,\s]*(?:<br\s*\/?>|\n|\r)*MineTech\s+Outbound[\s.]*<\/p>\s*$/i;
const GENERIC_HTML_CLOSING_RE = /<p>\s*(?:Best regards|Regards|Kind regards|Warmly|Sincerely|Cheers|Thanks|Best)[,\s]*(?:<br\s*\/?>|\n|\r)*(?:\[.*?\]|[A-Za-z\s]+)?\s*<\/p>\s*$/i;

/**
 * Ensures plain text email body ends with the complete official Abdullah Rauf / MineTech signature.
 * Idempotent: will not duplicate if signature is already present.
 */
export function ensureMineTechSignatureText(text = '') {
  if (!text || typeof text !== 'string') {
    return SIGNATURE_TEXT;
  }

  let cleaned = text.trim();

  // If it already ends with the signature (or a mangled/partial variant of Abdullah Rauf's signature), normalize it cleanly
  if (FULL_SIGNATURE_BLOCK_RE.test(cleaned)) {
    cleaned = cleaned.replace(FULL_SIGNATURE_BLOCK_RE, '').trim();
    return `${cleaned}\n\n${SIGNATURE_TEXT}`;
  }

  // If it ends with legacy "MineTech Outbound" signature, replace it
  if (LEGACY_SIGNATURE_RE.test(cleaned)) {
    cleaned = cleaned.replace(LEGACY_SIGNATURE_RE, '').trim();
    return `${cleaned}\n\n${SIGNATURE_TEXT}`;
  }

  // If there is a trailing sign-off placeholder (e.g. "Best regards,\nAlex" or "Regards,")
  if (GENERIC_CLOSING_RE.test(cleaned)) {
    cleaned = cleaned.replace(GENERIC_CLOSING_RE, '').trim();
  }

  return `${cleaned}\n\n${SIGNATURE_TEXT}`;
}

/**
 * Ensures HTML body ends with the complete official Abdullah Rauf / MineTech HTML signature.
 * Idempotent: will not duplicate if signature is already present.
 */
export function ensureMineTechSignatureHtml(html = '') {
  if (!html || typeof html !== 'string') {
    return SIGNATURE_HTML;
  }

  let cleaned = html.trim();

  // If HTML already contains the signature, return normalized
  if (HTML_SIGNATURE_IDENTIFIER_RE.test(cleaned)) {
    return cleaned;
  }

  // If HTML has legacy sign-off paragraph, replace it
  if (LEGACY_HTML_SIGNATURE_RE.test(cleaned)) {
    return cleaned.replace(LEGACY_HTML_SIGNATURE_RE, SIGNATURE_HTML);
  }

  // If there's a trailing generic sign-off paragraph, replace it
  if (GENERIC_HTML_CLOSING_RE.test(cleaned)) {
    return cleaned.replace(GENERIC_HTML_CLOSING_RE, SIGNATURE_HTML);
  }

  // If full HTML document, insert before </body>
  if (/<\/body>/i.test(cleaned)) {
    return cleaned.replace(/<\/body>/i, `${SIGNATURE_HTML}</body>`);
  }

  return `${cleaned}\n${SIGNATURE_HTML}`;
}

export default {
  SIGNATURE_DETAILS,
  SIGNATURE_TEXT,
  SIGNATURE_HTML,
  ensureMineTechSignatureText,
  ensureMineTechSignatureHtml,
};
